"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"

const OWNERS = ["Ana", "Ben", "Chloe", "Dev", "Eli", "Femi"]

export function ProjectFilters({ count }: { count: number }) {
  const [status, setStatus] = React.useState("all")
  const [owner, setOwner] = React.useState("")
  const active = status !== "all" || owner !== ""

  return (
    <div className="flex flex-col gap-4">
      <div className="flex flex-wrap items-center gap-2">
        <ToggleGroup
          type="single"
          variant="outline"
          value={status}
          onValueChange={(value) => setStatus(value || "all")}
          aria-label="Status"
        >
          <ToggleGroupItem value="all">All</ToggleGroupItem>
          <ToggleGroupItem value="active">Active</ToggleGroupItem>
          <ToggleGroupItem value="archived">Archived</ToggleGroupItem>
        </ToggleGroup>
        <Select value={owner} onValueChange={setOwner}>
          <SelectTrigger aria-label="Owner">
            <SelectValue placeholder="Owner" />
          </SelectTrigger>
          <SelectContent>
            {OWNERS.map((name) => (
              <SelectItem key={name} value={name}>
                {name}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        {active && (
          <Button
            variant="ghost"
            onClick={() => {
              setStatus("all")
              setOwner("")
            }}
          >
            Clear filters
          </Button>
        )}
      </div>
      <p aria-live="polite" className="text-sm text-muted-foreground">
        {count} {count === 1 ? "project" : "projects"}
      </p>
      {/* The collection: a Table, or an ItemGroup */}
    </div>
  )
}

saving.code_example:
"use client"

import * as React from "react"
import { WarningCircleIcon } from "@phosphor-icons/react"
import { toast } from "sonner"

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { Button } from "@/components/ui/button"
import { Field, FieldGroup, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import { Spinner } from "@/components/ui/spinner"

export function ProfileForm({
  save,
}: {
  save: (data: FormData) => Promise<void>
}) {
  const [pending, setPending] = React.useState(false)
  const [failed, setFailed] = React.useState(false)

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault()
    setPending(true)
    setFailed(false)
    try {
      await save(new FormData(event.currentTarget))
      toast.success("All set! Your changes are saved.")
    } catch {
      setFailed(true)
    } finally {
      setPending(false)
    }
  }

  return (
    <form onSubmit={handleSubmit} className="max-w-2xl">
      <FieldGroup>
        {failed && (
          <Alert variant="destructive">
            <WarningCircleIcon />
            <AlertTitle>We couldn't save your changes</AlertTitle>
            <AlertDescription>
              Check your connection and try again.
            </AlertDescription>
          </Alert>
        )}
        <Field>
          <FieldLabel htmlFor="display-name">Display name</FieldLabel>
          <Input id="display-name" name="displayName" defaultValue="Ana" />
        </Field>
        <div className="flex gap-2">
          <Button type="submit" disabled={pending} aria-busy={pending}>
            {pending ? (
              <>
                <Spinner aria-label="Saving changes" />
                Saving…
              </>
            ) : (
              "Save changes"
            )}
          </Button>
        </div>
      </FieldGroup>
    </form>
  )
}
